class SimpleRandomForest {
            constructor() {
                this.championEntries = null;
                this.championCount = 0;
                this.numTrees = 10; // Increased for better ensemble accuracy
                this.trees = [];
                this.featureSubsetSize = 5; // Number of features to consider per split
            }

            initializeChampionData() {
                if (!this.championEntries) {
                    this.championEntries = Object.entries(allChampions);
                    this.championCount = this.championEntries.length;
                    this.buildForest();
                }
            }

            // Build forest with bootstrap sampling
            buildForest() {
                this.trees = [];
                for (let i = 0; i < this.numTrees; i++) {
                    // Create bootstrap sample (random sampling with replacement)
                    const bootstrapSample = this.bootstrapSample();
                    this.trees.push({
                        id: i,
                        sample: bootstrapSample,
                        featureIndices: this.selectRandomFeatures()
                    });
                }
            }

            // Bootstrap sampling: random selection with replacement
            bootstrapSample() {
                const sample = [];
                for (let i = 0; i < this.championCount; i++) {
                    const randomIndex = Math.floor(Math.random() * this.championCount);
                    sample.push(this.championEntries[randomIndex]);
                }
                return sample;
            }

            // Random feature selection for each tree
            selectRandomFeatures() {
                const allFeatures = ['role', 'difficulty', 'damage', 'toughness', 'mobility', 'control', 'utility'];
                const selected = [];
                const shuffled = [...allFeatures].sort(() => Math.random() - 0.5);
                return shuffled.slice(0, this.featureSubsetSize);
            }

            predict(features) {
                this.initializeChampionData();

                // Collect votes from all trees (ensemble method)
                const votes = {};

                for (let i = 0; i < this.numTrees; i++) {
                    const tree = this.trees[i];
                    const prediction = this.singleTreePredict(features, tree);
                    votes[prediction] = (votes[prediction] || 0) + 1;
                }

                // Find champion with most votes (majority voting)
                let bestChampion = null;
                let maxVotes = 0;

                for (const [champion, voteCount] of Object.entries(votes)) {
                    if (voteCount > maxVotes) {
                        maxVotes = voteCount;
                        bestChampion = champion;
                    }
                }

                // Confidence is proportion of trees that voted for winner
                const confidence = (maxVotes / this.numTrees) * 100;

                return {
                    champion: bestChampion,
                    confidence: confidence,
                    algorithm: 'Random Forest'
                };
            }

            singleTreePredict(features, tree) {
                // Use only the random subset of features for this tree
                let bestChampion = null;
                let bestScore = -Infinity;

                // Evaluate champions in this tree's bootstrap sample
                for (const [name, champion] of tree.sample) {
                    let score = 0;

                    // Only use the randomly selected features for this tree
                    if (tree.featureIndices.includes('role')) {
                        score += (features.role === 'No Preference' || features.role === champion.role) ? 40 : 0;
                    }

                    if (tree.featureIndices.includes('difficulty')) {
                        const diffDist = Math.abs(features.difficulty - champion.difficulty);
                        score += Math.max(0, 20 - diffDist * 2);
                    }

                    if (tree.featureIndices.includes('damage')) {
                        const damageDist = Math.abs(features.damage - champion.damage);
                        score += Math.max(0, 15 - damageDist * 1.5);
                    }

                    if (tree.featureIndices.includes('toughness')) {
                        const toughDist = Math.abs(features.toughness - champion.toughness);
                        score += Math.max(0, 15 - toughDist * 1.5);
                    }

                    if (tree.featureIndices.includes('mobility')) {
                        score += champion.mobility >= 7 ? 10 : champion.mobility * 1.2;
                    }

                    if (tree.featureIndices.includes('control')) {
                        score += champion.control >= 7 ? 10 : champion.control * 1.2;
                    }

                    if (tree.featureIndices.includes('utility')) {
                        score += champion.utility >= 7 ? 10 : champion.utility * 1.2;
                    }

                    if (score > bestScore) {
                        bestScore = score;
                        bestChampion = name;
                    }
                }

                return bestChampion;
            }

            /**
             * Score all champions using Random Forest ensemble method
             * Each tree in the forest votes, and we aggregate the votes
             * 
             * @param {Object} features - User preference features
             * @returns {Object} Scores object with champion names as keys, score objects as values
             */
            predictAll(features) {
                const scores = {};
                this.initializeChampionData();

                // Get predictions from all trees for all champions
                const championVotes = {};

                for (let i = 0; i < this.numTrees; i++) {
                    const tree = this.trees[i];

                    // Each tree evaluates all champions
                    for (const [name, champion] of this.championEntries) {
                        const treeScore = this.calculateTreeScore(features, champion, tree);

                        if (!championVotes[name]) {
                            championVotes[name] = [];
                        }
                        championVotes[name].push(treeScore);
                    }
                }

                // Aggregate votes from all trees for each champion
                for (const [name, votes] of Object.entries(championVotes)) {
                    // Mean aggregation (average of all tree scores)
                    const meanScore = votes.reduce((sum, v) => sum + v, 0) / votes.length;

                    // Standard deviation (measure of disagreement between trees)
                    const variance = votes.reduce((sum, v) => sum + Math.pow(v - meanScore, 2), 0) / votes.length;
                    const stdDev = Math.sqrt(variance);

                    scores[name] = {
                        score: meanScore,
                        rawScore: meanScore,
                        uncertainty: stdDev, // Lower stdDev = more confident
                        details: {
                            contributingFactors: [{factor: 'Ensemble Average', weight: 100, contribution: meanScore}],
                            matchedCriteria: [`${this.numTrees} trees voted`],
                            penalties: []
                        }
                    };
                }

                return scores;
            }

            /**
             * Calculate score for a champion using specific tree's random feature subset
             * This is the core of Random Forest's randomness
             * 
             * @param {Object} features - User preferences
             * @param {Object} champion - Champion data
             * @param {Object} tree - Tree object with feature subset
             * @returns {number} Score from 0-100
             */
            calculateTreeScore(features, champion, tree) {
                let score = 0;
                let maxPossibleScore = 0;

                // Only use the randomly selected features for this tree
                if (tree.featureIndices.includes('role')) {
                    maxPossibleScore += 40;
                    if (features.role === 'No Preference' || features.role === champion.role) {
                        score += 40;
                    }
                }

                if (tree.featureIndices.includes('difficulty')) {
                    maxPossibleScore += 20;
                    const diffDist = Math.abs(features.difficulty - champion.difficulty);
                    score += Math.max(0, 20 - diffDist * 2);
                }

                if (tree.featureIndices.includes('damage')) {
                    maxPossibleScore += 15;
                    const damageDist = Math.abs(features.damage - champion.damage);
                    score += Math.max(0, 15 - damageDist * 1.5);
                }

                if (tree.featureIndices.includes('toughness')) {
                    maxPossibleScore += 15;
                    const toughDist = Math.abs(features.toughness - champion.toughness);
                    score += Math.max(0, 15 - toughDist * 1.5);
                }

                if (tree.featureIndices.includes('mobility')) {
                    maxPossibleScore += 10;
                    score += (champion.mobility / 10) * 10;
                }

                if (tree.featureIndices.includes('control')) {
                    maxPossibleScore += 10;
                    score += (champion.control / 10) * 10;
                }

                if (tree.featureIndices.includes('utility')) {
                    maxPossibleScore += 10;
                    score += (champion.utility / 10) * 10;
                }

                // Normalize to 0-100 range based on features used
                return maxPossibleScore > 0 ? (score / maxPossibleScore) * 100 : 0;
            }

            calculateChampionScore(features, champion) {
                // For individual champion scoring, use ensemble method
                const treeScores = [];

                for (const tree of this.trees) {
                    treeScores.push(this.calculateTreeScore(features, champion, tree));
                }

                const meanScore = treeScores.reduce((sum, s) => sum + s, 0) / treeScores.length;
                const variance = treeScores.reduce((sum, s) => sum + Math.pow(s - meanScore, 2), 0) / treeScores.length;

                return {
                    score: meanScore,
                    rawScore: meanScore,
                    details: {
                        contributingFactors: [{factor: 'Random Forest Ensemble', weight: 100, contribution: meanScore}],
                        matchedCriteria: [`Voted by ${this.numTrees} trees`],
                        penalties: [],
                        uncertainty: Math.sqrt(variance)
                    }
                };
            }
        }

class SimpleDecisionTree {
            /**
             * Scientifically accurate Decision Tree using Gini impurity for splits
             * 
             * A proper decision tree classifier that:
             * 1. Builds a tree by recursively splitting on features that minimize Gini impurity
             * 2. Uses Gini impurity: 1 - sum(p_i^2) where p_i is the proportion of class i
             * 3. Evaluates splits on all features (role, difficulty, damage, toughness, etc.)
             * 4. Stops splitting at max_depth or when node has min_samples
             * 5. Makes predictions by traversing the tree
             */
            constructor() {
                this.championEntries = null;
                this.championCount = 0;
                this.tree = null;
                this.maxDepth = 5;  // Maximum tree depth
                this.minSamples = 5;  // Minimum samples to split a node
            }

            initializeChampionData() {
                if (!this.championEntries) {
                    this.championEntries = Object.entries(allChampions);
                    this.championCount = this.championEntries.length;
                }
            }

            /**
             * Calculate Gini impurity for a set of samples
             * Gini = 1 - sum(p_i^2) where p_i is proportion of class i
             */
            calculateGini(samples) {
                if (samples.length === 0) return 0;

                const classCounts = {};
                for (const sample of samples) {
                    classCounts[sample.role] = (classCounts[sample.role] || 0) + 1;
                }

                let gini = 1.0;
                const totalSamples = samples.length;

                for (const role in classCounts) {
                    const proportion = classCounts[role] / totalSamples;
                    gini -= proportion * proportion;
                }

                return gini;
            }

            /**
             * Find best split for a feature based on Gini impurity reduction
             */
            findBestSplit(samples, feature) {
                let bestGini = Infinity;
                let bestSplit = null;

                // Get unique values for this feature
                const values = [...new Set(samples.map(s => s[feature]))];

                // Try splitting on each unique value
                for (const value of values) {
                    const leftSplit = samples.filter(s => s[feature] === value || 
                        (feature === 'position' && s.positions && s.positions.includes(value)));
                    const rightSplit = samples.filter(s => s[feature] !== value && 
                        !(feature === 'position' && s.positions && s.positions.includes(value)));

                    if (leftSplit.length === 0 || rightSplit.length === 0) continue;

                    // Weighted Gini impurity
                    const leftWeight = leftSplit.length / samples.length;
                    const rightWeight = rightSplit.length / samples.length;
                    const weightedGini = (leftWeight * this.calculateGini(leftSplit)) + 
                                        (rightWeight * this.calculateGini(rightSplit));

                    if (weightedGini < bestGini) {
                        bestGini = weightedGini;
                        bestSplit = { feature, value, leftSplit, rightSplit };
                    }
                }

                return { split: bestSplit, gini: bestGini };
            }

            /**
             * Build decision tree recursively
             */
            buildTree(samples, depth = 0) {
                // Stopping conditions
                if (depth >= this.maxDepth || samples.length < this.minSamples) {
                    // Leaf node - return most common role
                    const roleCounts = {};
                    for (const sample of samples) {
                        roleCounts[sample.role] = (roleCounts[sample.role] || 0) + 1;
                    }
                    const mostCommonRole = Object.keys(roleCounts).reduce((a, b) => 
                        roleCounts[a] > roleCounts[b] ? a : b
                    );
                    return {
                        isLeaf: true,
                        prediction: mostCommonRole,
                        samples: samples,
                        confidence: roleCounts[mostCommonRole] / samples.length
                    };
                }

                // Find best split across all features
                const features = ['role', 'difficulty', 'damage', 'toughness', 'mobility', 'control', 'utility'];
                let bestOverallSplit = null;
                let bestOverallGini = Infinity;

                for (const feature of features) {
                    const { split, gini } = this.findBestSplit(samples, feature);
                    if (split && gini < bestOverallGini) {
                        bestOverallGini = gini;
                        bestOverallSplit = split;
                    }
                }

                // If no good split found, create leaf
                if (!bestOverallSplit) {
                    const roleCounts = {};
                    for (const sample of samples) {
                        roleCounts[sample.role] = (roleCounts[sample.role] || 0) + 1;
                    }
                    const mostCommonRole = Object.keys(roleCounts).reduce((a, b) => 
                        roleCounts[a] > roleCounts[b] ? a : b
                    );
                    return {
                        isLeaf: true,
                        prediction: mostCommonRole,
                        samples: samples,
                        confidence: roleCounts[mostCommonRole] / samples.length
                    };
                }

                // Create internal node and recurse
                return {
                    isLeaf: false,
                    feature: bestOverallSplit.feature,
                    value: bestOverallSplit.value,
                    left: this.buildTree(bestOverallSplit.leftSplit, depth + 1),
                    right: this.buildTree(bestOverallSplit.rightSplit, depth + 1)
                };
            }

            /**
             * Train the decision tree (build it from champion data)
             */
            train() {
                this.initializeChampionData();
                const samples = this.championEntries.map(([name, champion]) => ({
                    name,
                    ...champion
                }));
                this.tree = this.buildTree(samples);
            }

            /**
             * Traverse tree to make a prediction
             */
            traverseTree(node, features) {
                if (node.isLeaf) {
                    return node;
                }

                // Check if feature matches
                let goLeft = false;
                if (node.feature === 'position') {
                    goLeft = features.position === node.value || features.position === 'No Preference';
                } else if (node.feature === 'role') {
                    goLeft = features.role === node.value || features.role === 'No Preference';
                } else if (node.feature === 'difficulty') {
                    goLeft = Math.abs(features.difficulty - node.value) <= 2;
                } else {
                    // Numeric features (damage, toughness, mobility, control, utility)
                    goLeft = features[node.feature] >= node.value - 2 && features[node.feature] <= node.value + 2;
                }

                if (goLeft) {
                    return this.traverseTree(node.left, features);
                } else {
                    return this.traverseTree(node.right, features);
                }
            }

            predict(features) {
                // Build tree if not already built
                if (!this.tree) {
                    this.train();
                }

                // Traverse tree to get prediction
                const leafNode = this.traverseTree(this.tree, features);

                // Get champions from leaf node that match user preferences
                const candidates = leafNode.samples.map(champion => {
                    let score = 100; // Start with base score

                    // Adjust based on psychological preferences
                    if (features.pressure_response === 'Stay calm and strategic' && champion.toughness >= 6) score += 15;
                    if (features.pressure_response === 'Take charge and lead' && (champion.damage >= 7 || champion.control >= 7)) score += 15;
                    if (features.pressure_response === 'Get aggressive and take risks' && champion.damage >= 8) score += 15;
                    if (features.pressure_response === 'Play cautiously to avoid mistakes' && champion.toughness >= 7) score += 15;

                    if (features.aesthetic_preference === 'Heroic' && champion.title && champion.title.includes('the')) score += 10;
                    if (features.aesthetic_preference === 'Mysterious' && (champion.role === 'Assassin' || champion.role === 'Mage')) score += 10;
                    if (features.aesthetic_preference === 'Dark and edgy' && champion.role === 'Assassin') score += 10;
                    if (features.aesthetic_preference === 'Cute or playful' && champion.role === 'Support') score += 10;
                    if (features.aesthetic_preference === 'Monstrous or non-human' && (champion.role === 'Fighter' || champion.role === 'Tank')) score += 10;

                    if (features.team_contribution === 'Lead and make decisions' && champion.control >= 7) score += 12;
                    if (features.team_contribution === 'Support and enable others' && champion.utility >= 7) score += 12;
                    if (features.team_contribution === 'Balance between both' && (champion.utility >= 5 && champion.control >= 5)) score += 12;
                    if (features.team_contribution === 'Stay independent and focus on my role' && champion.damage >= 7) score += 12;

                    if (features.problem_solving === 'Analyze carefully before acting' && champion.control >= 7) score += 10;
                    if (features.problem_solving === 'Jump in and adapt on the fly' && champion.mobility >= 7) score += 10;
                    if (features.problem_solving === "Follow the team's lead" && champion.utility >= 6) score += 10;
                    if (features.problem_solving === 'Focus on long-term improvement' && champion.toughness >= 7) score += 10;

                    return { name: champion.name, score };
                });

                // Apply diversity bonus and sort
                const diverseCandidates = applyDiversityBonus(candidates, recentRecommendations);
                diverseCandidates.sort((a, b) => b.score - a.score);
                const topCandidates = diverseCandidates.slice(0, Math.min(10, diverseCandidates.length));

                // Weighted selection
                const weights = topCandidates.map((_, i) => Math.pow(0.7, i));
                const totalWeight = weights.reduce((sum, w) => sum + w, 0);
                let random = Math.random() * totalWeight;

                for (let i = 0; i < topCandidates.length; i++) {
                    random -= weights[i];
                    if (random <= 0) {
                        return {
                            champion: topCandidates[i].name,
                            confidence: Math.min(95, Math.max(65, leafNode.confidence * 100)),
                            algorithm: 'Decision Tree'
                        };
                    }
                }

                return {
                    champion: topCandidates[0].name,
                    confidence: Math.min(95, Math.max(65, leafNode.confidence * 100)),
                    algorithm: 'Decision Tree'
                };
            }

            /**
             * Score all champions using decision tree
             */
            predictAll(features) {
                // Build tree if not already built
                if (!this.tree) {
                    this.train();
                }

                const scores = {};
                this.initializeChampionData();

                for (let i = 0; i < this.championCount; i++) {
                    const [name, champion] = this.championEntries[i];
                    const result = this.calculateChampionScore(features, champion);
                    scores[name] = result;
                }

                return scores;
            }

            /**
             * Calculate score for a single champion using tree-based approach with Gini impurity scoring
             */
            calculateChampionScore(features, champion) {
                let score = 0;
                const details = {
                    contributingFactors: [],
                    matchedCriteria: [],
                    penalties: []
                };

                // Use simplified tree-based scoring
                // Calculate match based on feature similarity

                // Role match (high weight)
                if (features.role === 'No Preference' || features.role === champion.role) {
                    score += 40;
                    details.contributingFactors.push({
                        factor: 'Role Match',
                        weight: 40,
                        contribution: 40
                    });
                    details.matchedCriteria.push(`Role: ${champion.role}`);
                } else {
                    score -= 20;
                    details.penalties.push(`Role mismatch: wanted ${features.role}, got ${champion.role}`);
                }

                // Position match
                const championPositions = champion.positions || [];
                if (features.position === 'No Preference' || 
                    (championPositions.length > 0 && championPositions.includes(features.position))) {
                    score += 30;
                    details.contributingFactors.push({
                        factor: 'Position Match',
                        weight: 30,
                        contribution: 30
                    });
                    details.matchedCriteria.push(`Position: ${features.position || 'Any'}`);
                } else if (features.position !== 'No Preference') {
                    score -= 15;
                    details.penalties.push(`Position mismatch: wanted ${features.position}`);
                }

                // Numeric feature similarities with Gini-inspired scoring
                const difficultyMatch = Math.max(0, 15 - Math.abs(features.difficulty - champion.difficulty) * 2);
                score += difficultyMatch;
                details.contributingFactors.push({
                    factor: 'Difficulty Similarity',
                    weight: 15,
                    contribution: difficultyMatch
                });

                const damageMatch = Math.max(0, 15 - Math.abs(features.damage - champion.damage) * 1.5);
                score += damageMatch;
                details.contributingFactors.push({
                    factor: 'Damage Similarity',
                    weight: 15,
                    contribution: damageMatch
                });

                const toughnessMatch = Math.max(0, 15 - Math.abs(features.toughness - champion.toughness) * 1.5);
                score += toughnessMatch;
                details.contributingFactors.push({
                    factor: 'Toughness Similarity',
                    weight: 15,
                    contribution: toughnessMatch
                });

                // Derived feature matches (new)
                const burstScore = Math.max(0, 10 - Math.abs((features.burst || 0) - (champion.derived_stats?.burst || 0)) / 5);
                score += burstScore;
                if (burstScore > 7) details.matchedCriteria.push(`Excellent Burst match`);

                const sustainScore = Math.max(0, 10 - Math.abs((features.sustain || 0) - (champion.derived_stats?.sustain || 0)) / 5);
                score += sustainScore;
                if (sustainScore > 7) details.matchedCriteria.push(`Excellent Sustain match`);

                // Psychological preferences (tree leaf adjustments)
                let psychScore = 0;

                if (features.pressure_response === 'Stay calm and strategic' && champion.toughness >= 6) psychScore += 15;
                if (features.pressure_response === 'Take charge and lead' && (champion.damage >= 7 || champion.control >= 7)) psychScore += 15;
                if (features.pressure_response === 'Get aggressive and take risks' && champion.damage >= 8) psychScore += 15;
                if (features.pressure_response === 'Play cautiously to avoid mistakes' && champion.toughness >= 7) psychScore += 15;

                if (features.aesthetic_preference === 'Heroic' && champion.title && champion.title.includes('the')) psychScore += 10;
                if (features.aesthetic_preference === 'Mysterious' && (champion.role === 'Assassin' || champion.role === 'Mage')) psychScore += 10;
                if (features.aesthetic_preference === 'Dark and edgy' && champion.role === 'Assassin') psychScore += 10;
                if (features.aesthetic_preference === 'Cute or playful' && champion.role === 'Support') psychScore += 10;
                if (features.aesthetic_preference === 'Monstrous or non-human' && (champion.role === 'Fighter' || champion.role === 'Tank')) psychScore += 10;

                if (features.team_contribution === 'Lead and make decisions' && champion.control >= 7) psychScore += 15;
                if (features.team_contribution === 'Support and enable others' && champion.utility >= 7) psychScore += 15;
                if (features.team_contribution === 'Balance between both' && (champion.utility >= 5 && champion.control >= 5)) psychScore += 15;
                if (features.team_contribution === 'Stay independent and focus on my role' && champion.damage >= 7) psychScore += 15;

                if (features.problem_solving === 'Analyze carefully before acting' && champion.control >= 7) psychScore += 10;
                if (features.problem_solving === 'Jump in and adapt on the fly' && champion.mobility >= 7) psychScore += 10;
                if (features.problem_solving === "Follow the team's lead" && champion.utility >= 6) psychScore += 10;
                if (features.problem_solving === 'Focus on long-term improvement' && champion.toughness >= 7) psychScore += 10;

                score += psychScore;
                details.contributingFactors.push({
                    factor: 'Psychological Match',
                    weight: 75,
                    contribution: psychScore
                });

                if (psychScore > 0) {
                    details.matchedCriteria.push(`Psychological preferences matched (${psychScore} points)`);
                }

                // Total max: 40+30+15+15+15+75 = 190 points (can be negative with penalties)
                const rawScore = score;
                const normalizedScore = this.normalizeScore(rawScore);

                return {
                    score: normalizedScore,
                    rawScore: rawScore,
                    details: details
                };
            }

            /**
             * Normalize raw score to 0-100 range
             */
            normalizeScore(rawScore) {
                const maxScore = 210;
                const minScore = -35; // Penalties

                const normalized = ((rawScore - minScore) / (maxScore - minScore)) * 100;
                return Math.max(0, Math.min(100, normalized));
            }
        }

class SimpleKNN {
            /**
             * Scientifically accurate K-Nearest Neighbors with proper normalization
             * 
             * Proper KNN algorithm that:
             * 1. Normalizes all numeric features to 0-1 range (prevents feature scale bias)
             * 2. Calculates Euclidean distance: sqrt(sum((x_i - y_i)^2))
             * 3. Selects K=7 nearest neighbors  
             * 4. Uses weighted voting: weight = 1 / (distance + small_epsilon)
             * 5. Returns weighted average of neighbor labels
             */
            constructor() {
                this.championEntries = null;
                this.championCount = 0;
                this.k = 7;  // Number of neighbors
                this.featureRanges = {
                    difficulty: { min: 1, max: 10 },
                    damage: { min: 1, max: 10 },
                    toughness: { min: 1, max: 10 },
                    mobility: { min: 1, max: 10 },
                    control: { min: 1, max: 10 },
                    utility: { min: 1, max: 10 }
                };
                this.weights = {
                    role: 2.5,
                    position: 1.5,
                    difficulty: 1.0,
                    damage: 1.2,
                    toughness: 1.2,
                    mobility: 1.0,
                    control: 1.0,
                    utility: 1.0,
                    burst: 0.8,
                    sustain: 0.8,
                    cc: 0.8
                };
            }

            initializeChampionData() {
                if (!this.championEntries) {
                    this.championEntries = Object.entries(allChampions);
                    this.championCount = this.championEntries.length;
                }
            }

            /**
             * Normalize a feature value to 0-1 range
             */
            normalize(value, featureName) {
                const range = this.featureRanges[featureName];
                if (!range) return value / 10; // Default normalization for 0-10
                return (value - range.min) / (range.max - range.min);
            }

            /**
             * Calculate Euclidean distance between user features and champion
             * Uses normalized features to prevent scale bias
             */
            calculateDistance(features, champion) {
                let sumSquares = 0;

                // Numeric features (normalized to 0-1)
                const numericFeatures = ['difficulty', 'damage', 'toughness', 'mobility', 'control', 'utility'];
                for (const feature of numericFeatures) {
                    const userValue = this.normalize(features[feature] || 5, feature);
                    const champValue = this.normalize(champion[feature] || 5, feature);
                    const diff = userValue - champValue;
                    sumSquares += this.weights[feature] * diff * diff;
                }

                // Derived features (0-100 range normalized to 0-1)
                const derivedFeatures = ['burst', 'sustain', 'cc'];
                for (const feature of derivedFeatures) {
                    const userValue = (features[feature] || 0) / 100;
                    const champValue = (champion.derived_stats?.[feature] || 0) / 100;
                    const diff = userValue - champValue;
                    sumSquares += this.weights[feature] * diff * diff;
                }

                // Categorical features (role and position)
                // Convert to binary: 0 if match, 1 if mismatch
                const roleMatch = (features.role === 'No Preference' || features.role === champion.role || features.role === champion.herotype) ? 0 : 1;
                sumSquares += this.weights.role * roleMatch * roleMatch;

                const championPositions = champion.positions || [];
                const positionMatch = (features.position === 'No Preference' || 
                    (championPositions.length > 0 && championPositions.includes(features.position))) ? 0 : 1;
                sumSquares += this.weights.position * positionMatch * positionMatch;

                // Euclidean distance
                return Math.sqrt(sumSquares);
            }

            predict(features) {
                this.initializeChampionData();

                // Calculate distances to all champions
                const distances = [];
                for (let i = 0; i < this.championCount; i++) {
                    const [name, champion] = this.championEntries[i];
                    const distance = this.calculateDistance(features, champion);
                    distances.push({ champion: name, distance, data: champion });
                }

                // Sort by distance (ascending - nearest first)
                distances.sort((a, b) => a.distance - b.distance);

                // Get K nearest neighbors
                const neighbors = distances.slice(0, this.k);

                // Weighted voting based on inverse distance
                let totalWeight = 0;
                const votes = {};

                for (const neighbor of neighbors) {
                    // Weight = 1 / (distance + epsilon) to avoid division by zero
                    const weight = 1 / (neighbor.distance + 0.001);
                    votes[neighbor.champion] = (votes[neighbor.champion] || 0) + weight;
                    totalWeight += weight;
                }

                // Add psychological preference adjustments
                for (const neighbor of neighbors) {
                    const champion = neighbor.data;
                    let bonusWeight = 0;

                    if (features.pressure_response === 'Stay calm and strategic' && champion.toughness >= 6) bonusWeight += 0.5;
                    if (features.pressure_response === 'Take charge and lead' && (champion.damage >= 7 || champion.control >= 7)) bonusWeight += 0.5;
                    if (features.pressure_response === 'Get aggressive and take risks' && champion.damage >= 8) bonusWeight += 0.5;
                    if (features.pressure_response === 'Play cautiously to avoid mistakes' && champion.toughness >= 7) bonusWeight += 0.5;

                    if (features.team_contribution === 'Lead and make decisions' && champion.control >= 7) bonusWeight += 0.3;
                    if (features.team_contribution === 'Support and enable others' && champion.utility >= 7) bonusWeight += 0.3;

                    votes[neighbor.champion] += bonusWeight;
                    totalWeight += bonusWeight;
                }

                // Convert to candidates array
                const candidates = Object.entries(votes).map(([champion, score]) => ({
                    champion,
                    score
                }));

                candidates.sort((a, b) => b.score - a.score);

                // Apply diversity bonus
                const diverseCandidates = applyDiversityBonus(candidates, recentRecommendations);
                diverseCandidates.sort((a, b) => b.score - a.score);
                const topCandidates = diverseCandidates.slice(0, Math.min(5, diverseCandidates.length));

                // Weighted selection
                const weights = topCandidates.map((_, i) => Math.pow(0.8, i));
                const totalWeightSelection = weights.reduce((sum, w) => sum + w, 0);
                let random = Math.random() * totalWeightSelection;

                for (let i = 0; i < topCandidates.length; i++) {
                    random -= weights[i];
                    if (random <= 0) {
                        return {
                            champion: topCandidates[i].champion,
                            confidence: Math.min(95, Math.max(75, (topCandidates[i].score / totalWeight) * 100)),
                            algorithm: 'K-Nearest Neighbors'
                        };
                    }
                }

                return {
                    champion: topCandidates[0].champion,
                    confidence: Math.min(95, Math.max(75, (topCandidates[0].score / totalWeight) * 100)),
                    algorithm: 'K-Nearest Neighbors'
                };
            }

            /**
             * Score all champions using KNN
             */
            predictAll(features) {
                this.initializeChampionData();
                const scores = {};

                for (let i = 0; i < this.championCount; i++) {
                    const [name, champion] = this.championEntries[i];
                    const result = this.calculateChampionScore(features, champion);
                    scores[name] = result;
                }

                return scores;
            }

            /**
             * Calculate score for a single champion using normalized Euclidean distance
             */
            calculateChampionScore(features, champion) {
                const distance = this.calculateDistance(features, champion);

                const details = {
                    contributingFactors: [{
                        factor: 'Weighted Euclidean Distance',
                        weight: 'N/A',
                        contribution: distance.toFixed(3)
                    }],
                    matchedCriteria: [],
                    penalties: []
                };

                // Add matched/mismatched criteria for transparency
                if (features.role === 'No Preference' || features.role === champion.role || features.role === champion.herotype) {
                    details.matchedCriteria.push(`Role/Herotype: ${champion.role}/${champion.herotype}`);
                } else {
                    details.penalties.push(`Role mismatch: wanted ${features.role}, got ${champion.role}`);
                }

                // Insights from derived features
                const burstDiff = Math.abs((features.burst || 0) - (champion.derived_stats?.burst || 0));
                if (burstDiff < 20) details.matchedCriteria.push(`Burst alignment: ${champion.derived_stats?.burst.toFixed(0)}%`);

                const sustainDiff = Math.abs((features.sustain || 0) - (champion.derived_stats?.sustain || 0));
                if (sustainDiff < 20) details.matchedCriteria.push(`Sustain alignment: ${champion.derived_stats?.sustain.toFixed(0)}%`);

                const ccDiff = Math.abs((features.cc || 0) - (champion.derived_stats?.cc || 0));
                if (ccDiff < 20) details.matchedCriteria.push(`CC alignment: ${champion.derived_stats?.cc.toFixed(0)}%`);

                const championPositions = champion.positions || [];
                if (features.position === 'No Preference' || 
                    (championPositions.length > 0 && championPositions.includes(features.position))) {
                    details.matchedCriteria.push(`Position: ${features.position || 'Any'}`);
                } else if (features.position !== 'No Preference') {
                    details.penalties.push(`Position mismatch: wanted ${features.position}`);
                }

                // Convert distance to score (lower distance = higher score)
                const normalizedScore = this.normalizeScore(distance);

                return {
                    score: normalizedScore,
                    rawScore: distance,
                    details: details
                };
            }

            /**
             * Normalize distance to 0-100 score
             */
            normalizeScore(distance) {
                // Max theoretical distance for normalized features
                // sqrt((1^2 * 6 numeric features) + (1^2 * 2 for role) + (1^2 * 1.5 for position)) ~= 3.24
                const maxDistance = 3.5;

                // Inverse relationship: distance 0 = score 100, distance maxDistance = score 0
                const normalized = Math.max(0, 100 - ((distance / maxDistance) * 100));
                return Math.max(0, Math.min(100, normalized));
            }
        }

class ScoreAggregator {
            /**
             * Aggregate scores from all three ML algorithms
             * @param {Object} rfScores - Random Forest scores object {championName: {score, rawScore, details}}
             * @param {Object} dtScores - Decision Tree scores object {championName: {score, rawScore, details}}
             * @param {Object} knnScores - KNN scores object {championName: {score, rawScore, details}}
             * @returns {Object} - Aggregated scores object with all champion scores
             */
            static aggregateScores(rfScores, dtScores, knnScores) {
                const aggregated = {};

                // Iterate through all champions
                for (const championName of Object.keys(allChampions)) {
                    // Get scores from each algorithm (default to 0 if not found)
                    const rf = rfScores[championName]?.score || 0;
                    const dt = dtScores[championName]?.score || 0;
                    const knn = knnScores[championName]?.score || 0;

                    // Calculate weighted score (Random Forest 40%, Decision Tree 30%, KNN 30%)
                    // This is now used as the primary "average" score for sorting and display
                    const average = (rf * 0.4) + (dt * 0.3) + (knn * 0.3);

                    // Calculate weighted score (redundant but kept for compatibility)
                    const weighted = this.calculateWeightedScore(rf, dt, knn);

                    // Store aggregated data
                    aggregated[championName] = {
                        championName: championName,
                        randomForest: rf,
                        decisionTree: dt,
                        knn: knn,
                        average: average,
                        weighted: weighted,
                        details: {
                            randomForest: rfScores[championName]?.details || null,
                            decisionTree: dtScores[championName]?.details || null,
                            knn: knnScores[championName]?.details || null
                        }
                    };
                }

                return aggregated;
            }

            /**
             * Calculate weighted score from three algorithm scores
             * @param {number} rf - Random Forest score (0-100)
             * @param {number} dt - Decision Tree score (0-100)
             * @param {number} knn - KNN score (0-100)
             * @returns {number} - Weighted score (0-100)
             */
            static calculateWeightedScore(rf, dt, knn) {
                // Apply weights: Random Forest 40%, Decision Tree 30%, KNN 30%
                const weighted = (rf * 0.4) + (dt * 0.3) + (knn * 0.3);

                // Ensure bounds
                return Math.max(0, Math.min(100, weighted));
            }

            /**
             * Select top 10 champions from aggregated scores
             * @param {Object} aggregatedScores - Aggregated scores object
             * @param {boolean} diversityFilter - Whether to apply diversity filter (default: true)
             * @returns {Array} - Array of 10 champion objects with scores
             */
            static selectTop10(aggregatedScores, diversityFilter = true) {
                // Convert object to array
                let champions = Object.values(aggregatedScores);

                // Sort by average score (descending)
                champions.sort((a, b) => b.average - a.average);

                // Apply diversity filter if enabled
                if (diversityFilter) {
                    champions = this.applyDiversityFilter(champions);
                }

                // Select top 10 champions
                const top10 = champions.slice(0, 10);

                // Ensure all are unique (should already be, but double-check)
                const uniqueChampions = [];
                const seenNames = new Set();

                for (const champion of top10) {
                    if (!seenNames.has(champion.championName)) {
                        uniqueChampions.push(champion);
                        seenNames.add(champion.championName);
                    }
                }

                // If we have less than 10 unique champions, fill from remaining
                if (uniqueChampions.length < 10) {
                    for (const champion of champions) {
                        if (!seenNames.has(champion.championName)) {
                            uniqueChampions.push(champion);
                            seenNames.add(champion.championName);

                            if (uniqueChampions.length >= 10) break;
                        }
                    }
                }

                return uniqueChampions;
            }

            /**
             * Apply diversity filter to limit champions per role
             * @param {Array} champions - Array of champion objects sorted by score
             * @returns {Array} - Filtered array with diversity applied
             */
            static applyDiversityFilter(champions) {
                const selected = [];
                const roleCount = {};

                // First pass: select champions with max 3 per role
                for (const champion of champions) {
                    const championData = allChampions[champion.championName];
                    const role = championData?.role || 'Unknown';

                    // Limit to max 3 champions per role in top 10
                    if ((roleCount[role] || 0) < 3) {
                        selected.push(champion);
                        roleCount[role] = (roleCount[role] || 0) + 1;
                    }

                    // Stop once we have 10 champions
                    if (selected.length >= 10) break;
                }

                // If we don't have 10 yet, add remaining highest scores regardless of role
                if (selected.length < 10) {
                    for (const champion of champions) {
                        // Check if not already selected
                        if (!selected.find(c => c.championName === champion.championName)) {
                            selected.push(champion);

                            if (selected.length >= 10) break;
                        }
                    }
                }

                return selected;
            }
        }

class EvaluationMetrics {
            /**
             * Calculate Precision@K metric
             * @param {Array<string>} recommendedChampions - Array of recommended champion names
             * @param {Set<string>} relevantChampions - Set of relevant champion names
             * @param {number} k - Number of top recommendations to consider
             * @returns {number} - Precision value between 0.0 and 1.0
             */
            static precisionAtK(recommendedChampions, relevantChampions, k) {
                // Handle edge cases
                if (!recommendedChampions || recommendedChampions.length === 0 || k === 0) {
                    return 0.0;
                }

                // Get top K recommendations
                const topK = recommendedChampions.slice(0, k);

                // Count how many are relevant
                let relevantCount = 0;
                for (const champion of topK) {
                    if (relevantChampions.has(champion)) {
                        relevantCount++;
                    }
                }

                // Calculate precision
                return relevantCount / topK.length;
            }

            /**
             * Calculate Recall@K metric
             * @param {Array<string>} recommendedChampions - Array of recommended champion names
             * @param {Set<string>} relevantChampions - Set of relevant champion names
             * @param {number} k - Number of top recommendations to consider
             * @returns {number} - Recall value between 0.0 and 1.0
             */
            static recallAtK(recommendedChampions, relevantChampions, k) {
                // Handle edge cases
                if (!recommendedChampions || recommendedChampions.length === 0 || k === 0) {
                    return 0.0;
                }

                if (relevantChampions.size === 0) {
                    return 0.0; // No relevant champions exist
                }

                // Get top K recommendations
                const topK = recommendedChampions.slice(0, k);

                // Count how many relevant champions are in top K
                let relevantCount = 0;
                for (const champion of topK) {
                    if (relevantChampions.has(champion)) {
                        relevantCount++;
                    }
                }

                // Calculate recall
                return relevantCount / relevantChampions.size;
            }

            /**
             * Calculate F1-Score@K metric
             * Harmonic mean of Precision@K and Recall@K
             * @param {Array<string>} recommendedChampions - Array of recommended champion names
             * @param {Set<string>} relevantChampions - Set of relevant champion names
             * @param {number} k - Number of top recommendations to consider
             * @returns {number} - F1-Score value between 0.0 and 1.0
             */
            static f1ScoreAtK(recommendedChampions, relevantChampions, k) {
                // Calculate Precision@K and Recall@K
                const precision = this.precisionAtK(recommendedChampions, relevantChampions, k);
                const recall = this.recallAtK(recommendedChampions, relevantChampions, k);

                // Handle edge case: both are 0
                if (precision === 0 && recall === 0) {
                    return 0.0;
                }

                // Calculate F1-Score (harmonic mean)
                const f1 = (2 * precision * recall) / (precision + recall);

                return f1;
            }

            /**
             * Calculate Mean Reciprocal Rank metric
             * @param {Array<string>} recommendedChampions - Array of recommended champion names
             * @param {Set<string>} relevantChampions - Set of relevant champion names
             * @returns {number} - MRR value between 0.0 and 1.0
             */
            static meanReciprocalRank(recommendedChampions, relevantChampions) {
                // Handle edge cases
                if (!recommendedChampions || recommendedChampions.length === 0) {
                    return 0.0;
                }

                // Find rank of first relevant champion (1-indexed)
                for (let i = 0; i < recommendedChampions.length; i++) {
                    if (relevantChampions.has(recommendedChampions[i])) {
                        return 1.0 / (i + 1);
                    }
                }

                // No relevant champion found
                return 0.0;
            }

            /**
             * Calculate user relevance based on questionnaire answers
             * ADAPTIVE APPROACH: Ensures we always have 10-20 relevant champions
             * COMPATIBILITY-BASED: Champions with 80%+ ML score are automatically relevant
             * 
             * @param {Object} userAnswers - User's questionnaire answers
             * @param {Object} allChampions - All available champions
             * @param {Object} mlScores - OPTIONAL: ML scores from recommendation results
             * @returns {Set<string>} - Set of relevant champion names
             */
            static calculateUserRelevance(userAnswers, allChampions, mlScores = null) {
                const championScores = [];

                // Extract user preferences - handle both object and array-like answers
                const userRole = userAnswers.role || userAnswers[2] || 'No Preference';
                const userPosition = userAnswers.position || userAnswers[3] || 'No Preference';
                const difficultyAnswer = userAnswers.difficulty || userAnswers[1];
                const playstyleAnswer = userAnswers.playstyle || userAnswers[4];

                const userDifficulty = this.mapDifficultyToNumeric(difficultyAnswer);
                const { damage: userDamage, toughness: userToughness } = this.mapPlaystyleToAttributes(playstyleAnswer);

                // Psychological preferences (Questions 6-10)
                const pressureResponse = userAnswers.pressure_response || userAnswers[6] || 'Stay calm and strategic';
                const aestheticPreference = userAnswers.aesthetic_preference || userAnswers[7] || 'Heroic';
                const teamContribution = userAnswers.team_contribution || userAnswers[8] || 'Balance between both';
                const characterIdentity = userAnswers.character_identity || userAnswers[9] || 'No preference';
                const problemSolving = userAnswers.problem_solving || userAnswers[10] || 'Analyze carefully before acting';

                // NEW: Get ML-scored champions if available (top 10 recommendations)
                const mlScoredChampions = new Set();
                if (mlScores && mlScores.top10) {
                    mlScores.top10.forEach(champion => {
