                // Score each champion using SAME logic as ML algorithms
                for (const [championName, champion] of Object.entries(allChampions)) {
                    let compatibilityScore = 0;
                    let maxPossibleScore = 0;

                    // 1. Role/Position match (40 points) - HIGHEST WEIGHT
                    maxPossibleScore += 40;
                    if (userRole === 'No Preference' || champion.role === userRole) {
                        compatibilityScore += 40;
                    } else if (userPosition !== 'No Preference' && champion.positions && champion.positions.includes(userPosition)) {
                        compatibilityScore += 30; // Partial credit for position match even if role doesn't match
                    }

                    // 2. Difficulty match (15 points) - RELAXED from ±1 to ±2
                    if (userDifficulty !== null) {
                        maxPossibleScore += 15;
                        const difficultyDiff = Math.abs(userDifficulty - champion.difficulty);
                        if (difficultyDiff === 0) {
                            compatibilityScore += 15; // Perfect match
                        } else if (difficultyDiff <= 1) {
                            compatibilityScore += 12; // Close match
                        } else if (difficultyDiff <= 2) {
                            compatibilityScore += 8; // Acceptable match
                        }
                        // difficultyDiff >= 3 gets 0 points
                    }

                    // 3. Damage match (12 points) - RELAXED from ±1 to ±2
                    if (userDamage !== null) {
                        maxPossibleScore += 12;
                        const damageDiff = Math.abs(userDamage - champion.damage);
                        if (damageDiff === 0) {
                            compatibilityScore += 12;
                        } else if (damageDiff <= 1) {
                            compatibilityScore += 10;
                        } else if (damageDiff <= 2) {
                            compatibilityScore += 6;
                        }
                    }

                    // 4. Toughness match (12 points) - RELAXED from ±1 to ±2
                    if (userToughness !== null) {
                        maxPossibleScore += 12;
                        const toughnessDiff = Math.abs(userToughness - champion.toughness);
                        if (toughnessDiff === 0) {
                            compatibilityScore += 12;
                        } else if (toughnessDiff <= 1) {
                            compatibilityScore += 10;
                        } else if (toughnessDiff <= 2) {
                            compatibilityScore += 6;
                        }
                    }

                    // 5. Psychological preferences (21 points) - NOW INCLUDED!
                    maxPossibleScore += 21;

                    // Pressure response (7 points)
                    if (pressureResponse === 'Stay calm and strategic' && champion.toughness >= 6) {
                        compatibilityScore += 7;
                    } else if (pressureResponse === 'Take charge and lead' && (champion.damage >= 7 || champion.control >= 7)) {
                        compatibilityScore += 7;
                    } else if (pressureResponse === 'Get aggressive and take risks' && champion.damage >= 8) {
                        compatibilityScore += 7;
                    } else if (pressureResponse === 'Play cautiously to avoid mistakes' && champion.toughness >= 7) {
                        compatibilityScore += 7;
                    } else {
                        compatibilityScore += 3; // Partial credit
                    }

                    // Team contribution (7 points)
                    if (teamContribution === 'Lead and make decisions' && champion.control >= 7) {
                        compatibilityScore += 7;
                    } else if (teamContribution === 'Support and enable others' && champion.utility >= 7) {
                        compatibilityScore += 7;
                    } else if (teamContribution === 'Balance between both' && (champion.utility >= 5 && champion.control >= 5)) {
                        compatibilityScore += 7;
                    } else if (teamContribution === 'Stay independent and focus on my role' && champion.damage >= 7) {
                        compatibilityScore += 7;
                    } else {
                        compatibilityScore += 3; // Partial credit
                    }

                    // Problem solving (7 points)
                    if (problemSolving === 'Analyze carefully before acting' && champion.control >= 7) {
                        compatibilityScore += 7;
                    } else if (problemSolving === 'Jump in and adapt on the fly' && champion.mobility >= 7) {
                        compatibilityScore += 7;
                    } else if (problemSolving === "Follow the team's lead" && champion.utility >= 6) {
                        compatibilityScore += 7;
                    } else if (problemSolving === 'Focus on long-term improvement' && champion.difficulty >= 7) {
                        compatibilityScore += 7;
                    } else {
                        compatibilityScore += 3; // Partial credit
                    }

                    // Calculate compatibility percentage
                    const compatibilityPercentage = maxPossibleScore > 0 ? (compatibilityScore / maxPossibleScore) * 100 : 0;

                    championScores.push({
                        name: championName,
                        score: compatibilityPercentage,
                        mlScored: mlScoredChampions.has(championName)
                    });
                }

                // Sort by compatibility score descending
                championScores.sort((a, b) => b.score - a.score);

                // ADAPTIVE APPROACH: Build relevant set with multiple criteria
                const relevantChampions = new Set();

                // STEP 1: Add all champions with 80%+ ML score (if available)
                mlScoredChampions.forEach(champion => relevantChampions.add(champion));

                // STEP 2: Add champions with high compatibility scores
                const topScore = championScores.length > 0 ? championScores[0].score : 0;
                const adaptiveThreshold = Math.max(topScore * 0.75, 60); // 75% of top score OR 60% minimum

                for (const champ of championScores) {
                    if (champ.score >= adaptiveThreshold) {
                        relevantChampions.add(champ.name);
                    }
                }

                // STEP 3: Ensure minimum of 10 relevant champions (adaptive floor)
                if (relevantChampions.size < 10) {
                    console.warn(`⚠️ Only ${relevantChampions.size} champions above threshold. Adding top ${10 - relevantChampions.size} to reach minimum.`);
                    for (let i = 0; i < championScores.length && relevantChampions.size < 10; i++) {
                        relevantChampions.add(championScores[i].name);
                    }
                }

                // STEP 4: Cap at maximum of 25 (prevents recall@10 from being too low)
                if (relevantChampions.size > 25) {
                    const cappedSet = new Set();
                    let count = 0;

                    // Prioritize ML-scored champions
                    for (const champ of championScores) {
                        if (mlScoredChampions.has(champ.name)) {
                            cappedSet.add(champ.name);
                            count++;
                        }
                    }

                    // Then add highest-scoring non-ML champions
                    for (const champ of championScores) {
                        if (count >= 25) break;
                        if (!mlScoredChampions.has(champ.name) && relevantChampions.has(champ.name)) {
                            cappedSet.add(champ.name);
                            count++;
                        }
                    }

                    console.log(`✂️ Capped relevant set from ${relevantChampions.size} to ${cappedSet.size} champions`);
                    console.log(`✅ Found ${cappedSet.size} relevant champions:`);
                    console.log(`   - ${mlScoredChampions.size} from ML scores (80%+ compatibility)`);
                    console.log(`   - ${cappedSet.size - mlScoredChampions.size} from adaptive threshold (${adaptiveThreshold.toFixed(1)}%)`);
                    console.log(`   - Top 5 scores: ${championScores.slice(0, 5).map(c => `${c.name}: ${c.score.toFixed(1)}%${c.mlScored ? ' (ML)' : ''}`).join(', ')}`);
                    return cappedSet;
                }

                console.log(`✅ Found ${relevantChampions.size} relevant champions:`);
                console.log(`   - ${mlScoredChampions.size} from ML scores (80%+ compatibility)`);
                console.log(`   - ${relevantChampions.size - mlScoredChampions.size} from adaptive threshold (${adaptiveThreshold.toFixed(1)}%)`);
                console.log(`   - Top 5 scores: ${championScores.slice(0, 5).map(c => `${c.name}: ${c.score.toFixed(1)}%${c.mlScored ? ' (ML)' : ''}`).join(', ')}`);

                return relevantChampions;
            }

            /**
             * Extract recommended champions from ML results
             * @param {Object} mlResults - Results from all ML algorithms (unified structure with top5 array)
             * @returns {Array<string>} - Array of 5 champion names in order (highest score first)
             */
            static getRecommendedChampions(mlResults) {
                // Check if mlResults has the new unified structure with top10 array
                if (mlResults && mlResults.top10 && Array.isArray(mlResults.top10)) {
                    // Extract top 10 champion names from mlResults.top10
                    // Maintain order (highest score first)
                    return mlResults.top10.map(champion => champion.championName);
                }

                // Fallback to legacy structure for backward compatibility
                const championScores = {};

                // Extract champions from each algorithm
                for (const [algorithmName, result] of Object.entries(mlResults)) {
                    if (result && result.champion) {
                        const championName = result.champion;
                        const confidence = result.confidence || 0;

                        // Collect confidence scores (use max if champion appears multiple times)
                        if (!championScores[championName] || championScores[championName] < confidence) {
                            championScores[championName] = confidence;
                        }
                    }
                }

                // Sort by confidence score descending
                const sortedChampions = Object.entries(championScores)
                    .sort((a, b) => b[1] - a[1])
                    .map(entry => entry[0]);

                return sortedChampions;
            }

            /**
             * Helper: Map difficulty string to numeric value
             * @param {string} difficulty - Difficulty string from questionnaire
             * @returns {number|null} - Numeric difficulty value or null
             */
            static mapDifficultyToNumeric(difficulty) {
                const mapping = {
                    'Easy (1-3)': 2,
                    'Medium (4-6)': 5,
                    'Hard (7-8)': 7.5,
                    'Very Hard (9-10)': 9.5
                };
                return mapping[difficulty] !== undefined ? mapping[difficulty] : null;
            }

            /**
             * Helper: Map playstyle to damage/toughness attributes
             * @param {string} playstyle - Playstyle string from questionnaire
             * @returns {Object} - Object with damage and toughness values
             */
            static mapPlaystyleToAttributes(playstyle) {
                const mapping = {
                    'High Damage Output': { damage: 8, toughness: 3 },
                    'Tanky and Durable': { damage: 4, toughness: 8 },
                    'Support Team': { damage: 3, toughness: 5 },
                    'Balanced/Hybrid': { damage: 5, toughness: 5 }
                };
                return mapping[playstyle] || { damage: null, toughness: null };
            }
        }

